mapper.select:
SELECT a.system_code ,a.module_code ,a.role_code ,a.role_name ,a.role_desc ,TO_CHAR(a.apply_start_date,'YYYY-MM-DD') AS apply_start_date ,TO_CHAR(a.apply_end_date,'YYYY-MM-DD') AS apply_end_date ,CASE WHEN (select COUNT(b.menu_id) from lgcom_role_menu_n b where a.role_code = b.role_code) > 0 THEN 'Y' ELSE 'N' END AS menu_flag ,CASE WHEN (select COUNT(role_business_organization_id) from lgcom_role_biz_org_n c where a.role_code = c.role_code) > 0 THEN 'Y' ELSE 'N' END AS org_flag FROM lgcom_role_m a WHERE 1=1 AND UPPER(a.role_code) like UPPER(#{roleCode}) || '%' AND UPPER(a.role_name) like UPPER(#{roleName}) || '%'
AND a.system_code = #{systemCode}
AND a.module_code = #{moduleCode}
ORDER BY a.system_code,a.module_code,a.role_code


SELECT 	COUNT(a.role_code) AS cnt
FROM 	lgcom_role_m a
WHERE   a.role_code = #{roleCode}
